<?php require __DIR__.'/_lib/config.php';
$w=['1=1'];$p=[];foreach(['kab'=>'l.kabupaten','status'=>'r.status','cat'=>'r.category_id'] as $k=>$col)if(!empty($_GET[$k])){$w[]="$col=?";$p[]=$_GET[$k];}
if(!empty($_GET['s'])){$w[]='(r.title LIKE ? OR l.address LIKE ?)';$p[]=$p[]='%'.$_GET['s'].'%';}
$rows=q('SELECT r.*,c.name cat,l.kabupaten,l.kecamatan,l.lat,l.lng FROM reports r JOIN locations l ON l.id=r.location_id JOIN report_categories c ON c.id=r.category_id WHERE '.implode(' AND ',$w).' ORDER BY r.id DESC',$p)->fetchAll();
$cats=q('SELECT * FROM report_categories')->fetchAll();head('Peta Lingkungan');?>
<div class="container py-4"><h3>Peta persebaran sampah</h3><form class="row g-2 mb-3"><div class="col-md-3"><input class="form-control" name="s" placeholder="Cari judul atau alamat" value="<?=e($_GET['s']??'')?>"></div>
<div class="col-md-3"><select class="form-select" name="kab"><option value="">Semua kabupaten/kota</option><?php foreach(KAB as $k):?><option <?=($_GET['kab']??'')==$k?'selected':''?>><?=$k?></option><?php endforeach?></select></div>
<div class="col-md-2"><select class="form-select" name="cat"><option value="">Semua kategori</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($_GET['cat']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></div>
<div class="col-md-2"><select class="form-select" name="status"><option value="">Semua status</option><?php foreach(STATUS as $s):?><option <?=($_GET['status']??'')==$s?'selected':''?>><?=$s?></option><?php endforeach?></select></div><div class="col-md-2"><button class="btn btn-eco w-100">Terapkan filter</button></div></form>
<p class="small"><span style="color:#EF4444">&#9679;</span> Baru &nbsp;<span style="color:#F59E0B">&#9679;</span> Diproses &nbsp;<span style="color:#10B981">&#9679;</span> Selesai</p>
<div class="row g-3"><div class="col-lg-8"><div id="map" class="map" style="height:520px"></div></div><div class="col-lg-4 side" style="max-height:520px"><?php if(!$rows):?><p class="text-muted">Tidak ada laporan yang cocok. Ubah filter untuk melihat lainnya.</p><?php endif;foreach($rows as $r):?><div class="card card-eco p-2 mb-2"><b><?=e($r['title'])?></b><small><?=e($r['cat'])?> &middot; <?=e($r['kabupaten'])?> &middot; <?=date('d M Y',strtotime($r['created_at']))?></small><div><?=badge($r['status'])?></div></div><?php endforeach?></div></div></div>
<?php foot("const m=L.map('map').setView(LL,9);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(m);const R=".json_encode($rows).";R.forEach(r=>L.marker([r.lat,r.lng],{icon:dot(r.status=='Selesai'?'#10B981':r.status=='Menunggu'?'#EF4444':r.status=='Ditolak'?'#6B7280':'#F59E0B')}).addTo(m).bindPopup('<b>'+r.title+'</b><br>'+r.cat+'<br>'+r.kabupaten+', '+r.kecamatan+'<br>'+r.created_at.slice(0,10)+'<br>Status: '+r.status));");
